function sealed(){return seals.filter(s=>s.got).length}
function showToast(msg){let el=document.getElementById('toast');el.innerHTML=msg;el.classList.add('show');toastTimer=2.3}
function updateHud(){let n=sealed(),b=biome(Math.floor(player.x/T));document.getElementById('zoneName').textContent=biomes[b][0].toUpperCase();document.getElementById('zoneSub').textContent=biomes[b][1].toUpperCase();document.getElementById('hearts').innerHTML=Array.from({length:player.maxHp},(_,i)=>`<i class="heart ${i>=player.hp?'empty':''}"></i>`).join('');document.getElementById('xp').style.width=`${Math.min(100,score*4)}%`;
 let title=n===3?'THE FINAL GATE':n===2?'ASHEN KEEP':n===1?'THE LOST SEALS':'AWAKE, WANDERER';let quest=n===3?'Reach the keep. Strike down the Demon King.':`Find the ${3-n} remaining ancient ${3-n===1?'seal':'seals'}.`;document.getElementById('questTitle').textContent=title;document.getElementById('questText').textContent=quest}
